    nums.__delitem__ = lambda i: nums.__delitem__(i)
    nums.__len__ = lambda: nums.__len__()

    def partition(start, end):
        pivot = nums[end]
        i = start
        for j in range(start, end):
            if nums[j] <= pivot:
                nums[i], nums[j] = nums[j], nums[i]
                i += 1
        nums[i], nums[end] = nums[end], nums[i]
