def solve(n, edges):
    def find(u):
        while u != root[u]:
            root[u] = root[root[u]]
            u = root[u]
        return u

    def union(u, v):
        root_u = find(u)
        root_v = find(v)
        if root_u != root_v:
            root[root_v] = root_u

    root = list(range(n))
    for u, v in edges:
        union(u, v)
    components = set()
    for i in range(n):
        components.add(find(i))
    return len(components)
```

