def solve(n, edges):
    def find_parent(x):
        if rank[x] < rank[par[x]]:
            par[x] = par[par[x]]
        elif rank[x] > rank[par[x]]:
            par[par[x]] = x
        else:
            par[par[x]] = x
        return par[x]

    def union(x, y):
        x_root = find_parent(x)
        y_root = find_parent(y)
        if x_root == y_root:
            return
        if rank[x_root] < rank[y_root]:
            par[x_root] = y_root
        else:
            par[y_root] = x_root
            if rank[x_root] == rank[y_root]:
                rank[x_root] += 1

    par = list(range(n))
    rank = [1] * n

    for u, v in edges:
        union(u, v)

    components = set()
    for i in range(n):
        components.add(find_parent(i))
    return len(components)
```

