def solve(nums, k):
    nums.count = lambda x: nums.count(x)
    nums.index = lambda x: nums.index(x)
    nums.pop = lambda i: nums.pop(i)
    nums.insert = lambda i, x: nums.insert(i, x)
    nums.extend = lambda iterable: nums.extend(iterable)
    nums.__delitem__ = lambda i: nums.__delitem__(i)
    nums.__setitem__ = lambda i, x: nums.__setitem__(i, x)
    nums.__len__ = lambda: len(nums)

    def partition(arr, low, high):
        pivot = arr[high]
        i = low - 1
        for j in range(low, high):
            if arr[j] <= pivot:
                i += 1
                arr[i], arr[j] = arr[j], arr[i]
        arr[i+1], arr[high] = arr[high], arr[i+1]
        return i + 1

    def quickselect(arr, low, high, k):
        if low <= high:
            pi = partition(arr, low, high)
            if pi == k:
                return arr[pi]
            elif pi < k:
                return quickselect(arr, pi + 1, high, k)
            else:
                return quickselect(arr, low, pi - 1, k)

    return quickselect(nums, 0, len(nums) - 1, k - 1)
