def solve(n, edges):
    def find(x):
        if father[x] != x:
            father[x] = find(father[x])
        return father[x]

    def union(x, y):
        fx = find(x)
        fy = find(y)
        if fx != fy:
            father[fy] = fx

    father = list(range(n))
    for u, v in edges:
        union(u, v)

    components = set()
    for i in range(n):
        components.add(find(i))

    return len(components)
```

